 "content": "def transform(grid):
    """Extend each solid 3x3 color block along its middle row and column."""
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    claims = [[set() for _ in range(w)] for _ in range(h)]

    # Locate monochrome 3x3 tiles; these are the line-generating objects.
    objects = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = original[r][c]
            if color == 0:
                continue
            if all(original[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                # Avoid redundant detections of the same 3x3 tile.
                if (r, c, color) not in objects:
                    objects.append((r, c, color))

    for r, c, color in objects:
        mid_r, mid_c = r + 1, c + 1
        for cc in range(w):
            claims[mid_r][cc].add(color)
        for rr in range(h):
            claims[rr][mid_c].add(color)

    result = [row[:] for row in original]
    for r in range(h):
        for c in range(w):
            if original[r][c] != 0:
                continue
            if len(claims[r][c]) == 1:
                result[r][c] = next(iter(claims[r][c]))
            # Crossings claimed by different colors remain blank.
    return result

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
